@Component("deal-entity-projector")
public class DealEntityProjector implements EntityProjector<Deal>{
		
	// core constructor
	public DealEntityProjector(ProjectorRegistry registry,
										DealRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Deal> getEntityClass() {
		return Deal.class;
	}

    /*
	 * Insert a Deal
	 * 
     * @param	entity Deal
     */
    public Deal create( Deal entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Deal
	 * 
     * @param	entity Deal
     */
    public Deal update( Deal entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Deal
	 * 
     * @param	id		UUID
     */
    public Deal delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Deal entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a Publisher
     * 
     * @param	parentId	UUID
     * @param	assignment 	Publisher 
     * @return	Deal
     */
    public Deal assignPublisher( UUID parentId, Publisher assignment ) {
	    LOGGER.info("assigning Publisher as " + assignment.toString() );

	    Deal parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Publisher.class, assignment.getPublisherId());

	    // ------------------------------------------
		// assign the Publisher to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPublisher( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Publisher
	 * 
	 * @param	parentId		UUID
	 * @return	Deal
	 */
	public Deal unAssignPublisher( UUID parentId ) {
		Deal parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Publisher on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Publisher on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPublisher(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the InventorySources
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Deal
     */
    public Deal addToInventorySources( UUID parentId, InventorySource addTo ) {
	    LOGGER.info("handling AssignInventorySourcesToDealEvent - " );
	    
	    Deal parentEntity = repository.findById(parentId).get();
	    InventorySource child = registry.project( InventorySource.class, addTo.getInventorySourceId());
	    
	    parentEntity.getInventorySources().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the InventorySources
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Deal
     */
	public Deal removeFromInventorySources( UUID parentId, InventorySource removeFrom ) {
	    LOGGER.info("handling RemoveInventorySourcesFromDealEvent " );
	
	    Deal parentEntity = repository.findById(parentId).get();
	    InventorySource child = registry.project( InventorySource.class, removeFrom.getInventorySourceId());
	    
	    parentEntity.getInventorySources().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the Placements
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Deal
     */
    public Deal addToPlacements( UUID parentId, Placement addTo ) {
	    LOGGER.info("handling AssignPlacementsToDealEvent - " );
	    
	    Deal parentEntity = repository.findById(parentId).get();
	    Placement child = registry.project( Placement.class, addTo.getPlacementId());
	    
	    parentEntity.getPlacements().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Placements
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Deal
     */
	public Deal removeFromPlacements( UUID parentId, Placement removeFrom ) {
	    LOGGER.info("handling RemovePlacementsFromDealEvent " );
	
	    Deal parentEntity = repository.findById(parentId).get();
	    Placement child = registry.project( Placement.class, removeFrom.getPlacementId());
	    
	    parentEntity.getPlacements().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Deal via an FindDealQuery
     * @return 	query	FindDealQuery
     */
    @SuppressWarnings("unused")
    public Deal find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Deal - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Deals
     *
     * @param	query	FindAllDealQuery 
     * @return 	List<Deal> 
     */
    @SuppressWarnings("unused")
    public List<Deal> findAll( FindAllDealQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Deal - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final DealRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(DealEntityProjector.class.getName());

}
